Apropos, it might make sense to construct large identifiers by pseudo-randomly composing from a predefined list of words, i.e

```C#
private static string[] s_Tokens = new [] { "XML", "Snake", "Camel", "Case" , "Parser", "Manager", "Visitor" ... };

private IEnumerable<string[]> GenerateIdentifiers(int count)
{
    var random = new Random(seed: 42);
    for (int i = 0; i < count; i++) 
        yield return GetTokens(random);
}

private string[] GetTokens(Random random)
{
     const int MaxTokens = 100;
     int tokens = random.Next(1, MaxTokens);
     var list = new List<string>(tokens);
     for (int i = 0; i < tokens; i++)
     {
          string nextToken = s_Tokens[random.Next(0, s_Tokens.Length)];
         tokens.Add(nextToken);
     }

     return tokens.ToArray();
}
```
With such tokens, it is fairly straightforward to compute both the PascalCase and kebab case/snake case renderings to be used to test the naming policy implementation.
